CREATE TABLE IF NOT EXISTS settings(owner TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE, history INTEGER NOT NULL DEFAULT 0, complete INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, query TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, created TEXT NOT NULL, updated INTEGER NOT NULL, expires INTEGER NOT NULL, history INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS jobs_owner_created ON jobs(owner,created);
CREATE TABLE IF NOT EXISTS credentials(owner TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, provider TEXT NOT NULL, encrypted TEXT NOT NULL, PRIMARY KEY(owner,provider));
CREATE TABLE IF NOT EXISTS usage(owner TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,provider TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,successes INTEGER NOT NULL DEFAULT 0,failures INTEGER NOT NULL DEFAULT 0,last_success TEXT,last_update TEXT,quota_limit REAL,remaining REAL,reset TEXT,confirmed INTEGER NOT NULL DEFAULT 0,blocked_until INTEGER NOT NULL DEFAULT 0,budget INTEGER,PRIMARY KEY(owner,provider));
CREATE TABLE IF NOT EXISTS provider_locks(provider TEXT PRIMARY KEY,next_request INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS footprint(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,url TEXT NOT NULL,username TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'unverified',created TEXT NOT NULL,challenge TEXT,monitoring INTEGER NOT NULL DEFAULT 0,interval_hours INTEGER NOT NULL DEFAULT 24,last_scan TEXT,snapshot TEXT);
CREATE INDEX IF NOT EXISTS footprint_owner ON footprint(owner);
CREATE TABLE IF NOT EXISTS alerts(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,profile_id TEXT NOT NULL,created TEXT NOT NULL,message TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quota_alert_settings(owner TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,thresholds TEXT NOT NULL DEFAULT '[50,80,90,100]');

CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS passkeys(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,public_key TEXT NOT NULL,counter INTEGER NOT NULL DEFAULT 0,transports TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS challenges(id TEXT PRIMARY KEY,challenge TEXT NOT NULL,kind TEXT NOT NULL,username TEXT,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS auth_limits(bucket TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
